#include "InterSiteFreightRuntime.hpp"
#include <cmath>
namespace elysium::logistics {bool InterSiteFreightRuntime::add(FreightManifest f,std::string&w){if(!f.id||!f.origin||!f.destination){w="invalid freight";return false;}double qty=0;for(auto&x:f.cargo)qty+=x.second;if(qty>f.capacity){w="over capacity";return false;}f.risk=std::clamp(std::isfinite(f.risk)?f.risk:0.0,0.0,1.0);return rows_.emplace(f.id,std::move(f)).second;}bool InterSiteFreightRuntime::advanceStrategic(StableId id,std::uint64_t t,std::string&w){auto i=rows_.find(id);if(i==rows_.end()){w="unknown freight";return false;}auto&f=i->second;if(f.stage==FreightStage::Planned&&t>=f.departure)f.stage=FreightStage::InTransit;if(f.stage==FreightStage::InTransit&&t>=f.arrival)f.stage=FreightStage::Arrived;return true;}bool InterSiteFreightRuntime::settle(StableId id,std::string&w){auto i=rows_.find(id);if(i==rows_.end()||i->second.stage!=FreightStage::Arrived){w="not arrived";return false;}i->second.stage=FreightStage::Transferred;return true;}std::optional<FreightManifest>InterSiteFreightRuntime::get(StableId id)const{auto i=rows_.find(id);if(i==rows_.end())return std::nullopt;return i->second;}}
